CustomField.formula:
IF(
OR(

/* Same territory as Account Owner */
Account.Owner.TPB_Territory__c = $User.TPB_Territory__c,

/* NSM coverage via parent territory */
Account.Owner.TPB_Parent_Territory__c = $User.TPB_Territory__c,

/* Directors (NSD) whose region prefix matches */
AND(
    $User.Title = "NSD",
    LEFT($User.Territory_Id__c,2) = LEFT(Account.Owner.Territory_Id__c,2)
),

/* Admin override */
$Profile.Name = "System Administrator",

/* Executive role */
$UserRole.Name = "Executive"

),
1,
0
)
